import { Component, input, output } from '@angular/core';
import { NzPaginationModule } from 'ng-zorro-antd/pagination';

/** hrm-pagination — phân trang, bọc nz-pagination. [pageIndex]/(pageIndexChange). */
@Component({
  selector: 'hrm-pagination',
  imports: [NzPaginationModule],
  template: `
    <nz-pagination
      [nzPageIndex]="pageIndex()"
      [nzTotal]="total()"
      [nzPageSize]="pageSize()"
      [nzShowSizeChanger]="showSizeChanger()"
      [nzSimple]="simple()"
      [nzResponsive]="responsive()"
      [nzSize]="size()"
      (nzPageIndexChange)="pageIndexChange.emit($event)"
      (nzPageSizeChange)="pageSizeChange.emit($event)"></nz-pagination>
  `,
  host: { class: 'hrm-pagination' },
})
export class HrmPagination {
  readonly pageIndex = input(1);
  readonly total = input(0);
  readonly pageSize = input(10);
  readonly showSizeChanger = input(false);
  readonly simple = input(false);
  /** Tự thu gọn số trang khi hẹp (nzResponsive) — tránh rớt hàng ở panel/drawer nhỏ. */
  readonly responsive = input(false);
  readonly size = input<'default' | 'small'>('default');
  readonly pageIndexChange = output<number>();
  readonly pageSizeChange = output<number>();
}
